import{_ as t,o,c as a,a3 as i}from"./chunks/framework.WFmvnizL.js";const h=JSON.parse('{"title":"Dashboard and MCP extensions","description":"Extend Nezha Dashboard REST APIs, MCP tools, and asynchronous work with explicit authorization, input contracts, cancellation, audit boundaries, and regression testing.","frontmatter":{"description":"Extend Nezha Dashboard REST APIs, MCP tools, and asynchronous work with explicit authorization, input contracts, cancellation, audit boundaries, and regression testing.","outline":"deep"},"headers":[],"relativePath":"en_US/developer/backend-development.md","filePath":"en_US/developer/backend-development.md","lastUpdated":1792850916000}'),n={name:"en_US/developer/backend-development.md"};function s(r,e,d,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="dashboard-and-mcp-extensions" tabindex="-1">Dashboard and MCP extensions <a class="header-anchor" href="#dashboard-and-mcp-extensions" aria-label="Permalink to &quot;Dashboard and MCP extensions&quot;">​</a></h1><p>Reuse existing REST APIs and capability layers first. Adding an endpoint requires resource permissions, input limits, response semantics, and lifecycle behavior, not just a route.</p><h2 id="locate-responsibilities" tabindex="-1">Locate responsibilities <a class="header-anchor" href="#locate-responsibilities" aria-label="Permalink to &quot;Locate responsibilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Location</th><th>Responsibility</th></tr></thead><tbody><tr><td>Routes/middleware</td><td><code>cmd/dashboard/controller/controller.go</code></td><td>Authentication groups, scopes, CSRF, route registration</td></tr><tr><td>Forms/responses/models</td><td><code>model</code></td><td>Input validation, JSON contracts, database structures</td></tr><tr><td>Handlers</td><td><code>cmd/dashboard/controller</code></td><td>HTTP/MCP protocol and business calls</td></tr><tr><td>Shared business/storage</td><td><code>service/singleton</code>, <code>pkg/tsdb</code></td><td>Caches, history, alerts, task lifecycle</td></tr><tr><td>Agent communication</td><td><code>cmd/dashboard/rpc</code>, <code>service/rpc</code>, <code>proto</code></td><td>gRPC, dispatch, streams, receipts</td></tr></tbody></table><p>Do not let UI clients submit every ORM field. Requests, stored models, and public responses need explicit, separate field boundaries.</p><h2 id="adding-rest-functionality" tabindex="-1">Adding REST functionality <a class="header-anchor" href="#adding-rest-functionality" aria-label="Permalink to &quot;Adding REST functionality&quot;">​</a></h2><ol><li>Define callers, input, output, and resource rules: guest-readable, member-owned, or administrator-only.</li><li>Define forms/responses with explicit JSON names and validate sizes, ranges, and enums.</li><li>Reuse JWT/PAT route authentication and enforce scopes. Browser cookie mutations remain CSRF-protected.</li><li>Check ownership/visibility and PAT server restrictions per resource, not just login. Avoid leaking distinctions between absent and inaccessible resources.</li><li>Use existing envelopes and distinguish empty, forbidden, unavailable, and accepted work. Add Swagger annotations and regenerate.</li><li>Test success, unauthorized access, missing scopes, allowlist exclusions, invalid inputs, concurrency, and cancellation. Update frontend and bilingual docs.</li></ol><p><strong>Visibility is not management permission.</strong> Members may see another user&#39;s public servers without acquiring modification or execution rights. Historical queries must enforce visibility and PAT restrictions too.</p><h2 id="adding-an-mcp-tool" tabindex="-1">Adding an MCP tool <a class="header-anchor" href="#adding-an-mcp-tool" aria-label="Permalink to &quot;Adding an MCP tool&quot;">​</a></h2><p>Native MCP currently covers identity, inventory/state, commands, and files. Alert configuration, history, and task management are not implicit methods. Check the <a href="/en_US/guide/mcp.html">tool inventory</a>; naming a tool in a client or feature page does not implement it.</p><p>Start with <code>controller/mcp.go</code>, <code>mcp_tools_*.go</code>, <code>mcp_transfer.go</code>, and related <code>service/rpc</code> code. Complete all of the following:</p><ul><li>JSON-RPC input schema, registration, dispatch, and protocol/error behavior matching existing implementation.</li><li>The <code>enable_mcp</code> kill switch, PAT-only authentication, and Origin checks; no browser-JWT fallback.</li><li>Minimal scopes, user resource permissions, PAT server allowlists, and corresponding Agent capability gates.</li><li>Input/output limits, timeouts/cancellation, PAT revocation, and cleanup when MCP is disabled.</li><li>Distinct command exit-code and execution-failure semantics; task acknowledgement is not command success.</li><li>Audit tool, target, outcome, and necessary metadata without recording PATs, sensitive file bodies, or unnecessary command output.</li></ul><p>File tools should reuse path restrictions, size limits, and integrity checks. Do not introduce download URLs that bypass authorization or turn the endpoint into an arbitrary public proxy.</p><p>The current transport uses <code>POST /mcp</code> request/response without standalone SSE push. <code>GET</code>/<code>DELETE /mcp</code> returning <code>405</code> is deliberate. Adapt clients to implemented transport instead of promising SSE only in documentation.</p><h2 id="state-changes-and-recovery" tabindex="-1">State changes and recovery <a class="header-anchor" href="#state-changes-and-recovery" aria-label="Permalink to &quot;State changes and recovery&quot;">​</a></h2><p>Distinguish accepted, running, terminal, and effectively applied states. After ambiguous timeouts on side-effecting requests, reconcile state before retrying. Multi-stage operations need persistent state, replay/idempotency rules, and recovery paths.</p><p>Persist configuration or credential transitions before irreversible cleanup/runtime changes. Use existing synchronization for shared state. Avoid putting atomic or synchronization fields inside response structs copied by value.</p><h2 id="what-to-include-in-a-contribution" tabindex="-1">What to include in a contribution <a class="header-anchor" href="#what-to-include-in-a-contribution" aria-label="Permalink to &quot;What to include in a contribution&quot;">​</a></h2><p>Provide contracts, permission matrices, regression cases, required migration/rollback notes, and <a href="/en_US/developer/testing.html">test evidence</a>. For Agent/protobuf changes, list paired commits. New UI routes must also check <a href="/en_US/developer/theme-development.html">SPA HTTP-status fallback</a>.</p><p>Authoritative implementation: <a href="https://github.com/nezhahq/nezha/blob/master/cmd/dashboard/controller/controller.go" target="_blank" rel="noreferrer">routes</a>, <a href="https://github.com/nezhahq/nezha/blob/master/cmd/dashboard/controller/scope_doc.go" target="_blank" rel="noreferrer">scope map</a>, <a href="https://github.com/nezhahq/nezha/blob/master/cmd/dashboard/controller/mcp.go" target="_blank" rel="noreferrer">MCP</a>.</p>',20)])])}const m=t(n,[["render",s]]);export{h as __pageData,m as default};
